<?php if (!$rangeValidations): range_empty('No validation reports', 'No quality validation has been performed.'); else: ?>
<div class="overflow-x-auto"><table class="w-full text-left border-collapse"><thead class="bg-surface-container-high/60 font-label-sm text-on-surface-variant uppercase"><tr><th class="py-2.5 px-3">Model</th><th class="py-2.5 px-3">Status</th><th class="py-2.5 px-3">Score</th><th class="py-2.5 px-3">Recorded</th><th class="py-2.5 px-3">Report</th></tr></thead><tbody class="divide-y divide-outline-variant/20 font-body-sm"><?php foreach ($rangeValidations as $vr): ?><tr><td class="py-2.5 px-3"><?= range_h($vr['model_code']) ?></td><td class="py-2.5 px-3"><?= range_h($vr['status']) ?></td><td class="py-2.5 px-3"><?= $vr['score'] === null ? 'NOT_EVALUATED' : range_h($vr['score']) ?></td><td class="py-2.5 px-3"><?= range_h($vr['created_at']) ?></td><td class="py-2.5 px-3"><a class="text-primary underline" href="<?= $rangeSystem === 'ml' ? '../Model Registry & Deployment/' : '' ?>ValidationReports.php?id=<?= (int)$vr['id'] ?>">Open report</a></td></tr><?php endforeach; ?></tbody></table></div>
<?php endif; ?>
